function id(e){return e.id&&e.id.$t?e.id.$t.split('post-').pop():'';}
function size(u,n){if(/lh3\.googleusercontent\.com\/d\//.test(u||''))return u.replace(/=s\d+.*$/,'')+'=s'+n;return (u||'').replace(/^http:\/\//i,'https://').replace(/\/(?:s\d+|w\d+-h\d+)(?:-[a-z0-9]+)*\//i,'/s'+n+'-rw/');}
function text(h){var d=document.createElement('div');d.innerHTML=h||'';d.querySelectorAll('script,style,noscript,table,svg,iframe').forEach(function(e){e.remove();});return (d.textContent||'').replace(/\s+/g,' ').trim();}
function excerpt(e,title){var v=items[id(e)];if(v&&v.desc&&e.updated&&v.updated===e.updated.$t)return text(v.desc);var s=text(e.summary?e.summary.$t:(e.content?e.content.$t:''));if(/^\s*\{\s*"@context"\s*:/.test(s))return '';for(var i=0;i<3;i++){if(title&&s.toLowerCase().indexOf(title.toLowerCase())===0)s=s.slice(title.length).replace(/^[\s:|.,-]+/,'');}s=s.replace(/^ASIA FX WATCH:\s*/i,'');if(/written and edited|post-title|display:block|by om kumar/i.test(s))return '';return s.length>210?s.slice(0,207).replace(/\s+\S*$/,'')+'…':s;}
function photo(e,n){var v=items[id(e)];return size(v&&v.photo?v.photo:(e.media$thumbnail&&e.media$thumbnail.url)||'',n);}
return {excerpt:excerpt,photo:photo};})();
