(function () {
    var button = document.getElementById('mobileMenuBtn');
    var menu = document.getElementById('primary-nav');
    var icon = document.getElementById('mobileMenuIcon');
    if (!button || !menu) return;

    function setMenu(open) {
        var returnFocus = !open && menu.classList.contains('active') && menu.contains(document.activeElement);
        menu.classList.toggle('active', open);
        button.setAttribute('aria-expanded', open ? 'true' : 'false');
        button.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
        if (icon) icon.className = open ? 'fas fa-times' : 'fas fa-bars';
        document.body.style.overflow = open ? 'hidden' : '';
        if (open && window.innerWidth <= 992) {
            var first = menu.querySelector('a[href], button:not([disabled])');
            if (first) first.focus();
        } else if (returnFocus) button.focus();
    }

    button.addEventListener('click', function (event) {
        event.preventDefault();
        event.stopPropagation();
        setMenu(!menu.classList.contains('active'));
    });

    menu.addEventListener('click', function (event) {
        var link = event.target.closest ? event.target.closest('a') : null;
        if (link && !link.classList.contains('dropdown-trigger')) setMenu(false);
    });

    document.addEventListener('keydown', function (event) {
        if (event.key === 'Escape') setMenu(false);
    });

    document.addEventListener('focusin', function (event) {
        if (window.innerWidth <= 992 && menu.classList.contains('active') &&
            !menu.contains(event.target) && event.target !== button) setMenu(false);
    });

    window.addEventListener('resize', function () {
        if (window.innerWidth > 992) setMenu(false);
    });
}());
