(function () {
  var nav = document.getElementById('primary-nav');
  if (!nav) return;
  var mobile = window.matchMedia('(max-width: 992px)');
  var records = [];
  nav.querySelectorAll('.nav-item-dropdown').forEach(function (group) {
    var trigger = group.querySelector('.dropdown-trigger');
    var submenu = group.querySelector('.nav-submenu');
    if (!trigger || !submenu) return;
    var closeTimer;
    function setOpen(open) {
      clearTimeout(closeTimer);
      group.classList.toggle('fx-nav-open', open);
      trigger.setAttribute('aria-expanded', String(open));
      submenu.hidden = !open;
    }
    function isOpen() { return trigger.getAttribute('aria-expanded') === 'true'; }
    records.push({ trigger: trigger, submenu: submenu, setOpen: setOpen });
    if (trigger.tagName === 'BUTTON') {
      trigger.addEventListener('click', function () { setOpen(!isOpen()); });
    } else {
      group.addEventListener('focusin', function (event) {
        if (!group.contains(event.relatedTarget)) setOpen(true);
      });
    }
    group.addEventListener('mouseenter', function () {
      clearTimeout(closeTimer);
      if (!mobile.matches) setOpen(true);
    });
    group.addEventListener('mouseleave', function () {
      if (!mobile.matches && !group.contains(document.activeElement)) {
        closeTimer = setTimeout(function () {
          if (!group.contains(document.activeElement)) setOpen(false);
        }, 200);
      }
    });
    group.addEventListener('focusout', function (event) {
      if (!mobile.matches && !group.contains(event.relatedTarget)) setOpen(false);
    });
    group.addEventListener('keydown', function (event) {
      if (event.key === 'Escape' && isOpen()) {
        event.preventDefault();
        event.stopPropagation();
        setOpen(false);
        trigger.focus();
      }
    });
  });
  function syncViewport() {
    if (mobile.matches && !nav.classList.contains('active') && nav.contains(document.activeElement)) {
      var menuButton = document.getElementById('mobileMenuBtn');
      if (menuButton) menuButton.focus();
    }
    records.forEach(function (record) {
      if (!mobile.matches && record.submenu.contains(document.activeElement)) record.trigger.focus();
      record.setOpen(mobile.matches);
    });
  }
  syncViewport();
  mobile.addEventListener('change', syncViewport);
}());
