(function() {
    function articleURL(bar) {
        var url = new URL(bar.getAttribute('data-share-url'), window.location.href);
        if (url.protocol !== 'https:' && url.protocol !== 'http:') throw new Error('Unsupported article URL');
        return url.href;
    }
    document.querySelectorAll('.floating-share-bar').forEach(function(bar) {
        var title = bar.getAttribute('data-share-title') || document.title;
        var url;
        try { url = articleURL(bar); } catch (error) { return; }
        document.body.classList.add('fxrl-has-article-share');
        document.documentElement.classList.add('fxrl-has-article-share');
        var destinations = [
            ['whatsapp', 'https://api.whatsapp.com/send', {text: title + ' ' + url}],
            ['twitter', 'https://twitter.com/intent/tweet', {text: title, url: url}],
            ['linkedin', 'https://www.linkedin.com/shareArticle', {mini: 'true', url: url, title: title}],
            ['facebook', 'https://www.facebook.com/sharer/sharer.php', {u: url}]
        ];
        destinations.forEach(function(item) {
            var link = bar.querySelector('.share-btn.' + item[0]);
            if (!link) return;
            var target = new URL(item[1]);
            Object.keys(item[2]).forEach(function(key) { target.searchParams.set(key, item[2][key]); });
            link.href = target.href;
        });
    });
    window.fxrlCopyArticleLink = async function(button) {
        if (button.getAttribute('data-copy-pending') === 'true') return;
        button.setAttribute('data-copy-pending', 'true');
        button.setAttribute('aria-busy', 'true');
        button.setAttribute('aria-disabled', 'true');
        try {
            var bar = button.closest('.floating-share-bar');
            var url = articleURL(bar);
            if (!navigator.clipboard || typeof navigator.clipboard.writeText !== 'function') throw new Error('Clipboard unavailable');
            await navigator.clipboard.writeText(url);
            window.alert('Article link copied!');
        } catch (error) {
            window.alert('Could not copy the link. Copy it from your browser address bar.');
        } finally {
            button.removeAttribute('data-copy-pending');
            button.removeAttribute('aria-busy');
            button.removeAttribute('aria-disabled');
        }
    };
})();
