  (function() {
    // Config
    var currentUrl = window.location.href.split("?")[0].split("#")[0];
    var maxResults = 3;

    // Get Label from Blogger Tags
    var firstLabel = "";
    <b:if cond='data:post.labels'>
      <b:loop values='data:post.labels' var='label' index='i'>
        <b:if cond='data:i == 0'>firstLabel = "<data:label.name/>";</b:if>
      </b:loop>
    </b:if>

    // Function to display posts
    window.renderRelated = function(json) {
      var container = document.getElementById('related-posts-grid');
      var html = '';
      var entries = json.feed.entry || [];
      var count = 0;

      for (var i = 0; i < entries.length; i++) {
        var entry = entries[i];
        var postLink = "";
        for (var k = 0; k < entry.link.length; k++) {
          if (entry.link[k].rel == 'alternate') {
            postLink = entry.link[k].href.split("?")[0].split("#")[0];
            break;
          }
        }

        // Skip current post
        if (postLink === currentUrl) continue;
        if (count >= maxResults) break;

        var postTitle = entry.title.$t;
        var thumb = "https://via.placeholder.com/400x225?text=FX+Rate+Live";
        if (entry.media$thumbnail) {
          thumb = entry.media$thumbnail.url.replace(/\/s\d+-c\//, "/w400-h225-c/");
        }

        html += '<a href="' + postLink + '" class="rp-card">';
        html += '<img src="' + thumb + '" loading="lazy" decoding="async" class="rp-img" alt="' + postTitle + '"/>';
        html += '<div class="rp-content"><h4 class="rp-title">' + postTitle + '</h4></div></a>';
        count++;
      }

      if (html !== "") {
        container.innerHTML = html;
      } else {
        container.innerHTML = "<p>No more articles found.</p>";
      }
    };

    // Create Script URL
    var feedUrl = "/feeds/posts/summary";
    if (firstLabel !== "") {
      feedUrl += "/-/" + encodeURIComponent(firstLabel);
    }

    var script = document.createElement('script');
    script.src = feedUrl + "?alt=json-in-script&max-results=5&callback=renderRelated";
    document.head.appendChild(script);

    // Back Button Logic
    const allArticlesPage = "/p/article-archives.html"; 
    if (document.referrer.includes(allArticlesPage)) {
      document.getElementById('back-to-all-container').style.display = 'block';
      document.getElementById('back-to-all-link').href = document.referrer;
    }
  })();
