body.script:
    //
        // 1. DATA: Currencies
        const currencies = [
            {c:'USD',n:'US Dollar',f:'us',country:'United States'}, {c:'EUR',n:'Euro',f:'eu',country:'Eurozone'}, 
            {c:'INR',n:'Indian Rupee',f:'in',country:'India'}, {c:'GBP',n:'British Pound',f:'gb',country:'United Kingdom'}, 
            {c:'AED',n:'UAE Dirham',f:'ae',country:'UAE'}, {c:'AUD',n:'Australian Dollar',f:'au',country:'Australia'},
