            {c:'CNY',n:'Chinese Yuan',f:'cn',country:'China'}, {c:'BTC',n:'Bitcoin',f:'xk',country:'Digital'},
            {c:'ETH',n:'Ethereum',f:'xk',country:'Digital'}, {c:'SAR',n:'Saudi Riyal',f:'sa',country:'Saudi Arabia'},
            {c:'SGD',n:'Singapore Dollar',f:'sg',country:'Singapore'}, {c:'ZAR',n:'South African Rand',f:'za',country:'South Africa'},
            {c:'PKR',n:'Pakistani Rupee',f:'pk',country:'Pakistan'}, {c:'MXN',n:'Mexican Peso',f:'mx',country:'Mexico'},
            {c:'BRL',n:'Brazilian Real',f:'br',country:'Brazil'}, {c:'RUB',n:'Russian Ruble',f:'ru',country:'Russia'},
            {c:'KRW',n:'South Korean Won',f:'kr',country:'South Korea'}, {c:'TRY',n:'Turkish Lira',f:'tr',country:'Turkey'},
            {c:'CHF',n:'Swiss Franc',f:'ch',country:'Switzerland'}, {c:'HKD',n:'Hong Kong Dollar',f:'hk',country:'Hong Kong'},
            {c:'NZD',n:'New Zealand Dollar',f:'nz',country:'New Zealand'}, {c:'SEK',n:'Swedish Krona',f:'se',country:'Sweden'},
            {c:'NOK',n:'Norwegian Krone',f:'no',country:'Norway'}, {c:'DKK',n:'Danish Krone',f:'dk',country:'Denmark'},
            {c:'PLN',n:'Polish Zloty',f:'pl',country:'Poland'}, {c:'THB',n:'Thai Baht',f:'th',country:'Thailand'},
            {c:'IDR',n:'Indonesian Rupiah',f:'id',country:'Indonesia'}, {c:'MYR',n:'Malaysian Ringgit',f:'my',country:'Malaysia'}
        ];


        const cryptoPrices = {'BTC':92171.16, 'ETH':3450.50, 'USD':1};
        const apiBase = "https://api.exchangerate-api.com/v4/latest/USD";
        let myChart = null;
        let lastRate = 1.0;

        // 2. SEO CONTENT (FULL ARTICLES)
        const currencyProfileDB={
            'USD': `
            <div style="text-align:left; font-family:'Inter', sans-serif;">

                <!-- Hero Header -->
                <div style="background:linear-gradient(135deg, #0a3161 0%, #b31942 100%); color:white; padding:30px; border-radius:12px; margin-bottom:25px; display:flex; align-items:center; gap:20px; box-shadow:0 4px 15px rgba(10, 49, 97, 0.3);">
                    <span class="flag-icon flag-icon-us" style="font-size:4rem; border-radius:4px; box-shadow:0 4px 10px rgba(255,255,255,0.2);"></span>
                    <div>
                        <h1 style="margin:0; font-size:2.2rem; font-weight:800; text-shadow:0 2px 4px rgba(0,0,0,0.3);">United States Dollar (USD)</h1>
                        <p style="margin:5px 0 0; font-size:1.1rem; opacity:1; font-weight:600;">The Global Reserve Currency</p>
                    </div>
                </div>

                <div class="article-body">
                    <p>The <strong>United States Dollar ($)</strong>, often referred to as the <em>"Greenback,"</em> is the official currency of the United States. It is the undisputed king of the financial world, accounting for nearly <strong>60% of all global central bank reserves</strong> and 90% of all forex trade volume.</p>

                    <h2 style="color:var(--primary); margin-top:30px;">1. The Power of the Federal Reserve (The Fed)</h2>
                    <p>The value of the Dollar is managed by the <strong><a href="https://www.federalreserve.gov/" target="_blank" style="color:var(--primary); text-decoration:underline;">Federal Reserve System</a></strong>. The Fed is considered the most powerful financial institution on the planet.</p>
                    <ul>
                        <li><strong>Interest Rates:</strong> When the Fed raises rates, the Dollar strengthens because global investors buy US Bonds to earn higher interest.</li>
                        <li><strong>Quantitative Easing (QE):</strong> When the Fed prints money to stimulate the economy, the Dollar can weaken due to increased supply.</li>
                    </ul>

                    <h2 style="color:var(--primary); margin-top:30px;">2. Why is Everything Priced in USD?</h2>
                    <p>The USD is the standard currency for commodities. Whether it is <strong>Gold, Crude Oil, Copper, or Wheat</strong>, global prices are set in Dollars. This system, often called the "Petrodollar" system for oil, ensures that every country needs USD to survive and trade.</p>
                    <div style="background:var(--input-bg); padding:20px; border-left:5px solid var(--accent); border-radius:8px; margin:20px 0;">
                        <strong>💡 Live Analysis:</strong> Check how the Dollar Strength (DXY) is affecting commodities in our <a href="#" onclick="openNewsModal()" style="color:var(--primary); font-weight:bold;">Market News Section</a>.
                    </div>

                    <h2 style="color:var(--primary); margin-top:30px;">3. Safe Haven Status</h2>
                    <p>In times of crisis—be it war, a pandemic, or a stock market crash—investors follow the motto: <em>"Cash is King."</em> And by cash, they mean the US Dollar. The USD tends to appreciate during global uncertainty because the US economy is seen as the most stable and liquid market in the world.</p>

                    <h2 style="color:var(--primary); margin-top:30px;">4. Major Currency Pairs</h2>
                    <p>If you are trading or converting, these are the most liquid pairs involving the USD:</p>
                    <ul style="margin-left:20px; line-height:1.8;">
                        <li><strong>EUR/USD:</strong> The most traded pair in the world.</li>
                        <li><strong>USD/JPY:</strong> A battle between US yields and Japanese stability.</li>
                        <li><strong>GBP/USD:</strong> Known as "The Cable," famous for its volatility.</li>
                    </ul>

                    <div style="text-align:center; margin-top:30px;">
                        <button onclick="closeNewsModal(); setFrom('USD'); calculate(); document.getElementById('converter').scrollIntoView({behavior:'smooth'})" style="background:#0a3161; color:white; border:none; padding:12px 30px; border-radius:50px; font-weight:bold; cursor:pointer;">Check Live USD Rates</button>
                    </div>
                </div>
            </div>
        `,


        };



function init() {
    const f = document.getElementById('fromCurr');
    const t = document.getElementById('toCurr');

    if (f && t) {
        currencies.forEach(c => {
            f.add(new Option(`${c.c} - ${c.n}`, c.c));
            t.add(new Option(`${c.c} - ${c.n}`, c.c));
        });

        const urlParams = new URLSearchParams(window.location.search);
        const fromParam = urlParams.get('from');
        const toParam = urlParams.get('to');

        if (fromParam) f.value = fromParam;
        if (toParam) t.value = toParam;

        document.getElementById("datePicker").valueAsDate = new Date();
        updateApp();

        // AGAR URL mein parameters hain, toh page load hote hi scroll karein
        if (fromParam || toParam) {
            setTimeout(performProScroll, 500); 
        }
    }

    generateMiddleGrids(); 
    renderFrontPageNews();

    if (document.getElementById('fxChart')) {
        setTimeout(() => updateChartTimeframe('1m'), 1000);
    }
}


        function updateApp(){
            const fVal=document.getElementById('fromCurr').value;const tVal=document.getElementById('toCurr').value;
            const fObj=currencies.find(c=>c.c===fVal)||{f:'xk',n:fVal,country:'Global'};
            const tObj=currencies.find(c=>c.c===tVal)||{f:'xk',n:tVal,country:'Global'};
            document.getElementById('flag1').className=`flag-icon flag-icon-${fObj.f}`;
            document.getElementById('flag2').className=`flag-icon flag-icon-${tObj.f}`;
            document.getElementById('guideTitle').innerText=`${fVal} to ${tVal}: Complete Guide`;

            let p1 = currencyProfileDB[fVal] ? currencyProfileDB[fVal] : `<h1>${fObj.n}</h1><p>Official currency of ${fObj.country}.</p>`;
            let p2 = currencyProfileDB[tVal] ? currencyProfileDB[tVal] : `<h1>${tObj.n}</h1><p>Official currency of ${tObj.country}.</p>`;

            document.getElementById('currencyProfiles').innerHTML=`
                <div class="profile-card"><div class="profile-header"><span class="flag-icon flag-icon-${fObj.f}"></span> ${fObj.c} - ${fObj.n}</div><div class="profile-desc">The ${fObj.n} is the official currency of ${fObj.country}.</div><div style="margin-top:10px; color:var(--primary); font-weight:bold; cursor:pointer; font-size:0.9rem;" onclick="openProfilePopup('${fVal}')">📖 Read Full ${fVal} Profile</div></div>
                <div class="profile-card"><div class="profile-header"><span class="flag-icon flag-icon-${tObj.f}"></span> ${tObj.c} - ${tObj.n}</div><div class="profile-desc">The ${tObj.n} is the official currency of ${tObj.country}.</div><div style="margin-top:10px; color:var(--primary); font-weight:bold; cursor:pointer; font-size:0.9rem;" onclick="openProfilePopup('${tVal}')">📖 Read Full ${tVal} Profile</div></div>`;
            calculate();
        }

        async function calculate() {
            const f = document.getElementById('fromCurr').value;
            const t = document.getElementById('toCurr').value;
            const amt = parseFloat(document.getElementById('amount').value) || 1;
            const date = document.getElementById('datePicker').value;
            const isToday = new Date(date).toDateString() === new Date().toDateString();

            try {
                let rate = 0;
                if(isToday) {
                    const res = await fetch(apiBase);
                    const data = await res.json();
                    let rateFrom = data.rates[f];
                    let rateTo = data.rates[t];
                    if(!rateFrom && cryptoPrices[f]) rateFrom = 1 / cryptoPrices[f];
                    if(!rateTo && cryptoPrices[t]) rateTo = 1 / cryptoPrices[t];
                    if(!rateFrom) rateFrom = 1; if(!rateTo) rateTo = 1;
                    rate = rateTo / rateFrom;
                    document.getElementById('dateText').innerText = "Live Rate";
                } else {
                    const seed = date.split('').reduce((a,b)=>a+b.charCodeAt(0),0);
                    rate = (1 + (seed % 50)/100); 
                    document.getElementById('dateText').innerText = "Historical (" + date + ")";
                }

                lastRate = rate;
                let decimals = (rate < 0.1 || t === 'BTC' || t === 'ETH' || f === 'BTC' || f === 'ETH') ? 8 : 4;
                if (rate > 1000) decimals = 2;




document.getElementById('result').value = (amt * rate).toFixed(decimals);
const rateTextElem = document.getElementById('rateText');
rateTextElem.classList.remove('skeleton-loader'); 
rateTextElem.innerText = `1 ${f} = ${rate.toFixed(decimals)} ${t}`;



                generateTables(rate, f, t);
                const activeBtn = document.querySelector('.chart-btn.active');
                if(activeBtn) updateChartTimeframe(activeBtn.innerText.toLowerCase());

            } catch(e) { console.log(e); }
        }

        function generateTables(rate, f, t) {
            const amts = [1, 5, 10, 50, 100, 500, 1000];
            let dec = rate < 1 ? 6 : 2;
            let invDec = (1/rate) < 1 ? 6 : 2;
            document.getElementById('tblTitle1').innerText = `Convert ${f} to ${t}`;
            document.getElementById('tblBody1').innerHTML = amts.map(a => `<div class="adv-row"><span>${a} ${f}</span><span style="font-weight:700;">${(a*rate).toFixed(dec)} ${t}</span></div>`).join('');
            document.getElementById('tblTitle2').innerText = `Convert ${t} to ${f}`;
            document.getElementById('tblBody2').innerHTML = amts.map(a => `<div class="adv-row"><span>${a} ${t}</span><span style="font-weight:700;">${(a*(1/rate)).toFixed(invDec)} ${f}</span></div>`).join('');
        }

        function updateChartTimeframe(p) {
            document.querySelectorAll('.chart-btn').forEach(b => b.classList.remove('active'));
            const btns = Array.from(document.querySelectorAll('.chart-btn'));
            const btn = btns.find(b => b.innerText.toLowerCase() === p.toLowerCase());
            if(btn) btn.classList.add('active');

            const ctx = document.getElementById('fxChart').getContext('2d');
            const isDark = document.body.getAttribute('data-theme') === 'dark';
            let count=30, vol=0.05, labels=[];
            p = p.toLowerCase();
            if(p==='48h') { count=24; vol=0.005; labels=Array.from({length:24},(_,i)=>i+":00"); }
            else if(p==='1w') { count=7; vol=0.02; labels=["Mon","Tue","Wed","Thu","Fri","Sat","Sun"]; }
            else if(p==='1m') { count=30; vol=0.05; labels=Array.from({length:30},(_,i)=>i+1); }
            else { count=12; vol=0.15; labels=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"]; }

            let data=[], curr=lastRate;
            for(let i=0; i<count; i++) {
                let change = (Math.random() - 0.5) * (vol * 2);
                curr = curr * (1 + change); 
                data.push(curr);
            }

            if(myChart) myChart.destroy();
            myChart = new Chart(ctx, {
                type: 'line',
                data: {
                    labels: labels,
                    datasets: [{
                        label: 'Rate', data: data,
                        borderColor: isDark?'#4ade80':'#009e4f',
                        backgroundColor: isDark?'rgba(74,222,128,0.1)':'rgba(0,158,79,0.05)',
                        borderWidth: 2, fill: true, pointRadius: p==='1m'?0:3, tension: 0.4
                    }]
                },
                options: {
                    responsive: true, maintainAspectRatio: false,
                    plugins: { legend: { display: false } },
                    scales: { x: { display: p!=='1m' }, y: { grid: { color: isDark?'#333':'#eee' }, ticks: { callback: function(val) { return val < 0.01 ? val.toExponential(2) : val.toLocaleString(); } } } }
                }
            });
        }






function generateMiddleGrids() {
    const cGrid = document.getElementById('otherCurrenciesGrid');
    if (cGrid) {
        cGrid.innerHTML = currencies.slice(0, 30).map(c =>

            `<a href="javascript:void(0);" onclick="setFrom('${c.c}')" class="link-card"><span class="flag-icon flag-icon-${c.f}"></span> ${c.n}</a>`
        ).join('');
    }

    const pGrid = document.getElementById('popularConversionsGrid');
    if (pGrid) {
        const pairs = ["USD/EUR","GBP/USD","USD/JPY","AUD/USD","USD/CAD","USD/INR","EUR/GBP","USD/CHF","USD/CNY","USD/AED","BTC/USD","ETH/USD","USD/ZAR","USD/SGD","USD/MXN","USD/HKD","USD/KRW","USD/TRY","USD/BRL","USD/RUB","USD/SAR","USD/PKR","USD/THB","USD/MYR"];
        pGrid.innerHTML = pairs.map(p => {
            const [f, t] = p.split('/');

            return `<a href="javascript:void(0);" onclick="setPair('${f}','${t}')" class="link-card">${f} to ${t}</a>`;
        }).join('');
    }
}

function renderFrontPageNews() {
    var container = document.getElementById('frontPageNewsContainer');
    if (!container || typeof newsData === 'undefined') return;

    var newsHtml = '';
    var latestNews = newsData; // **सभी उपलब्ध आइटम दिखाएँ**

    latestNews.forEach(function(n) {
        // **सुरक्षित इमेज URL हैंडलिंग:** &amp; को & से बदलें और एरर हैंडलिंग जोड़ें
        var safeImg = n.img ? n.img.replace(/&amp;/g, '&') : 'https://via.placeholder.com/100x70?text=FX';

        newsHtml += '<div class="fp-news-item" onclick="openArticle(' + n.id + ')">' + 
            '<div style="width:100px; height:70px; flex-shrink:0; border-radius:8px; overflow:hidden; background:#eee;">' +
                // 'onerror' इवेंट जोड़ा गया ताकि इमेज फेल होने पर भी कुछ दिखे
                '<img src="' + safeImg + '" loading="lazy" decoding="async" class="fp-news-thumb" alt="news" onerror="this.onerror=null; this.src=\'https://via.placeholder.com/100x70?text=FX\'"/>' +
            '</div>' +
            '<div class="fp-news-content" style="flex-grow:1;">' +
                '<div class="fp-meta" style="font-size:11px; margin-bottom:4px; display:flex; gap:10px;">' +
                    '<span class="fp-tag" style="color:var(--primary); font-weight:700;">' + n.c + '</span>' +
                    '<span class="fp-time">' + n.d + '</span>' +
                '</div>' +
                '<div class="fp-title" style="font-size:14px; font-weight:600; color:var(--text); line-height:1.4;">' + n.t + '</div>' +
            '</div>' +
        '</div>';
    });

    container.innerHTML = newsHtml;
    container.style.display = "block";
}


        function openContent(key){document.getElementById('newsPopup').style.display='block';document.getElementById('newsListView').style.display='none';document.getElementById('newsReaderView').style.display='block';document.getElementById('articleContent').innerHTML=footerContentDB[key]||`<h1>${key}</h1><p>Content loading...</p>`;}
