            document.getElementById('articleContent').innerHTML = `
                <div style="text-align:left; font-family:'Inter', sans-serif;">
                    <div style="border-bottom:1px solid var(--border); padding-bottom:20px; margin-bottom:30px;">
                        <span style="background:var(--primary); color:#fff; padding:5px 15px; border-radius:50px; font-size:0.8rem; font-weight:bold;">AUTOMATED ANALYSIS</span>
                        <h1 style="margin-top:15px; font-size:2.2rem; line-height:1.2; color:var(--text);">Convert ${fObj.n} to ${tObj.n}: Live Trends & Forecast</h1>
                        <p style="color:var(--text-light); margin-top:10px;">Daily Mid-Market Data • ${new Date().toLocaleDateString()}</p>
                    </div>

                    <div class="article-body">
                        <p style="font-size:1.1rem; line-height:1.8;">You are analyzing the exchange rate between <strong>${fObj.n} (${f})</strong> and <strong>${tObj.n} (${t})</strong>. The current market rate is <strong>${lastRate.toFixed(4)}</strong>.</p>

                        <h3 style="color:var(--primary); margin-top:25px;">Market Drivers</h3>
