    latestNews.forEach(function(n) {
        var safeImg = n.img ? n.img.replace(/&amp;/g, '&') : 'https://via.placeholder.com/100x70?text=FX';

        newsHtml += '<div class="fp-news-item" onclick="openArticle(' + n.id + ')" style="display:flex; align-items:center; gap:15px; padding:12px; border-bottom:1px solid var(--border); cursor:pointer;">' +
            '<div style="width:100px; height:70px; flex-shrink:0; border-radius:8px; overflow:hidden; background:#eee;">' +
                '<img src="' + safeImg + '" style="width:100%; height:100%; object-fit:cover;" alt="news" />' +
            '</div>' +
            '<div class="fp-news-content" style="flex-grow:1;">' +
                '<div class="fp-meta" style="font-size:11px; margin-bottom:4px; display:flex; gap:10px;">' +
                    '<span class="fp-tag" style="color:var(--primary); font-weight:700;">' + n.c + '</span>' +
                    '<span class="fp-time">' + n.d + '</span>' +
                '</div>' +
                '<div class="fp-title" style="font-size:15px; font-weight:600; color:var(--text); line-height:1.4;">' + n.t + '</div>' +
            '</div>' +
        '</div>';
    });
    container.innerHTML = newsHtml;
}


    document.getElementById('articleContent').innerHTML = 
        '<img src="' + safeImg + '" style="width:100%;height:300px;object-fit:cover;border-radius:10px;margin-bottom:20px;" onerror="this.src=\'https://via.placeholder.com/800x400?text=FX+News\'"/>' +
        '<h1 style="font-size:2rem; margin-bottom:15px; color:var(--text);">' + n.t + '</h1>' +
        shareButtonsHTML + 
        '<div class="article-body">' + n.content + '</div>';

    document.getElementById('newsPopup').scrollTop = 0;
}













function performProScroll() {
    // Hum 'hero-wrapper' ko target karenge taaki Title bhi dikhe
    var heroElement = document.querySelector('.hero-wrapper');
    if (heroElement) {
        // Offset scroll logic taaki sticky header ke piche na chhupa jaye
        const offset = 80; // Header height ke hisaab se adjust karein
        const bodyRect = document.body.getBoundingClientRect().top;
        const elementRect = heroElement.getBoundingClientRect().top;
        const elementPosition = elementRect - bodyRect;
        const offsetPosition = elementPosition - offset;

        window.scrollTo({
            top: offsetPosition,
            behavior: "smooth"
        });
    } else {
        window.scrollTo({ top: 0, behavior: "smooth" }); 
    }
}


function setFrom(c) {
    var fs = document.getElementById('fromCurr');
    if (fs) { 
        // Home page par hain
        fs.value = c; 
        updateApp(); 
        performProScroll(); 
    } else {
        // Static page par hain, Home par bhejein parameters ke saath
        window.location.href = '/?from=' + c;
    }
}

function setPair(f, t) {
    var fs = document.getElementById('fromCurr');
    var ts = document.getElementById('toCurr');
    if (fs && ts) { 
        // Home page par hain
        fs.value = f; 
        ts.value = t; 
        updateApp(); 
        performProScroll(); 
    } else {
        // Static page par hain, Home par bhejein parameters ke saath
        window.location.href = '/?from=' + f + '&to=' + t;
    }
}


function swap() {
    var f = document.getElementById('fromCurr'), t = document.getElementById('toCurr');
    var tmp = f.value; 
    f.value = t.value; 
    t.value = tmp; 
    updateApp(); 
    performProScroll();
}

function shareApp(){
    if(navigator.share){
        navigator.share({title:'FX Rate Live',url:window.location.href});
    } else {
        alert('Link copied to clipboard!');
    }
}

function toggleTheme(){
    document.body.setAttribute('data-theme', document.body.getAttribute('data-theme')==='dark'?'light':'dark');
}

function toggleLang(){
    document.getElementById('langMenu').classList.toggle('show-lang');
}

function setLang(l){
    document.getElementById('currentLang').innerText=l;
    document.getElementById('langMenu').classList.remove('show-lang');
}


function setupInteractiveLinks() {


    const otherCurrGridContainer = document.getElementById('otherCurrenciesGrid');
    if (otherCurrGridContainer) {
        otherCurrGridContainer.querySelectorAll('.link-card').forEach(link => {
            link.addEventListener('click', function() {
                // हम मानते हैं कि HTML में आपने 'data-currency-code' 
                const code = this.getAttribute('data-currency-code');
                if (code) {
                    setFrom(code); 
                }
            });
        });
    }

    // B. "Popular Conversions" 
    const popularGridContainer = document.getElementById('popularConversionsGrid');
    if (popularGridContainer) {
        popularGridContainer.querySelectorAll('.link-card').forEach(link => {
            link.addEventListener('click', function() {
                const f = this.getAttribute('data-from');
                const t = this.getAttribute('data-to');
                if (f && t) {
                    setPair(f, t); 
                }
            });
        });
    }
}



document.addEventListener('DOMContentLoaded', init); 



